<!doctype html><html><head><meta charset="utf-8"><title>Invoice {{ $invoice->invoice_number }}</title><style>body{font-family:Arial,sans-serif;background:#f5f7fb;color:#111827;margin:0}.sheet{max-width:900px;margin:30px auto;background:#fff;padding:42px;border-radius:20px;box-shadow:0 8px 30px rgba(15,23,42,.08)}.top{display:flex;justify-content:space-between;gap:30px;border-bottom:2px solid #111827;padding-bottom:24px}.brand{font-size:28px;font-weight:900}.muted{color:#64748b}.meta{text-align:right}.grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:30px 0}.box{background:#f8fafc;padding:18px;border-radius:14px}.items{width:100%;border-collapse:collapse}.items th,.items td{padding:13px;border-bottom:1px solid #e5e7eb;text-align:left}.items th{background:#f8fafc}.totals{margin-left:auto;width:320px;margin-top:24px}.row{display:flex;justify-content:space-between;padding:7px 0}.grand{font-size:20px;font-weight:900;border-top:2px solid #111827;padding-top:12px}.qr{margin-top:28px;padding:15px;border:1px dashed #94a3b8;border-radius:14px;text-align:center}.qr code{font-size:11px;word-break:break-all}.footer{margin-top:30px;text-align:center;color:#64748b;font-size:12px}@media print{body{background:#fff}.sheet{box-shadow:none;margin:0;max-width:none;border-radius:0}} </style></head><body><main class="sheet"><header class="top"><div><div class="brand">CHACHA PRIME</div><div class="muted">Premium Commerce Invoice</div></div><div class="meta"><strong>{{ $invoice->invoice_number }}</strong><br><span class="muted">Order: {{ $invoice->order_number }}</span><br><span class="muted">Issued: {{ $invoice->issued_at }}</span></div></header><section class="grid"><div class="box"><strong>Billing Address</strong><p>{{ $invoice->billing_address ?: 'Same as shipping address' }}</p></div><div class="box"><strong>Shipping Address</strong><p>{{ $invoice->shipping_address }}</p></div></section><table class="items"><thead><tr><th>Item</th><th>SKU</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>@foreach($items as $item)<tr><td>{{ $item->title }}</td><td>{{ $item->sku }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->unit_price,2) }}</td><td>{{ number_format($item->total_amount,2) }}</td></tr>@endforeach</tbody></table><section class="totals"><div class="row"><span>Subtotal</span><span>{{ number_format($invoice->subtotal,2) }}</span></div><div class="row"><span>Discount</span><span>-{{ number_format($invoice->discount_amount,2) }}</span></div><div class="row"><span>Shipping</span><span>{{ number_format($invoice->shipping_amount,2) }}</span></div><div class="row"><span>Tax</span><span>{{ number_format($invoice->tax_amount,2) }}</span></div><div class="row grand"><span>Total</span><span>{{ number_format($invoice->total_amount,2) }} {{ $invoice->currency }}</span></div></section><div class="qr"><strong>Invoice QR</strong><p><code>{{ $invoice->qr_payload }}</code></p></div><div class="footer">Payment method: {{ $invoice->payment_method ?: 'N/A' }} · Thank you for shopping with Chacha Prime.</div></main><script>window.print()</script></body></html>